#!/usr/bin/env python3
"""
Homicide worldwide, fourth patch (culprits), 17 October 2026. Needs the third
homicide patch (homicide_culprits3.py, already applied on main).

The within-countries row now covers 83 countries and Europe's regions; the
reader waits longer for the map's files.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTE = "## Homicide worldwide, fourth patch (17 October, a separate chat)\n\nNeeds the third homicide patch (guards on its heading). Not a numbered round;\nthis note goes at the end of this file. Files go into the maps repo by hand.\nNo tiles patch. No app.js?v= bump.\n\n- Owner, 17 October: look again (three more times) for the countries where\n  nothing open turned up below the national level; add New Zealand despite\n  its terms.\n- Found: El Salvador (Medicina Legal, departments and municipalities,\n  2002-2021), Nicaragua, Bolivia, Paraguay, Puerto Rico (municipalities),\n  Sri Lanka (police divisions), Nepal (one narrow category), Rwanda, Iran\n  (provinces), Germany (deaths by assault by state, Destatis via GBE-Bund;\n  Eurostat NUTS assault deaths), Belgium and Turkey (Eurostat NUTS assault\n  deaths), Russia (federal subjects 2006-2017, Wikipedia citing EMISS, marked\n  secondary), Ukraine (regional prosecutors' Form 1 reports, CC BY), Iraq\n  (two research papers), Haiti (UN mission counts of people killed by gangs,\n  by commune), New Zealand (NZ Police offender proceedings by territorial\n  authority, 2014-2026; NZ Police terms allow non-commercial use and forbid\n  alteration without permission: added at the owner's word), and police\n  figures quoted in named news reports or journals, labelled as such: Ghana,\n  Zambia, Namibia, Botswana, Guyana, Bangkok, Hanoi, Chongqing.\n  Still nothing below the national level: Jordan, Egypt, Morocco, Eswatini.\n- The owner's first upload put the country files in the maps repo folder\n  homicide_maps_upload/ (not homicide_within/); the map now reads that\n  folder, so nothing uploaded had to move. It now holds 86 files.\n- Shading: a level is shaded by murder rather than a side offence (driving,\n  conspiracy, attempts and the like) when murder covers at least half the\n  areas. Sources whose monthly tables leave out months with nothing recorded\n  (New Zealand) no longer show full years as incomplete.\n- The within reading takes about 168 s locally (21,891 areas, 192 overlays):\n  registry.json homicide_within \"wait\" 240000 (was 120000). Its name and\n  app.js note say 83 countries, name the news-quoted sources and the folder.\n"

DIFF = ""

FILES = ["map/app.js", "pipeline/sitemaps/registry.json"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("homicide4: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Homicide worldwide, third patch (17 October" not in h.read_text(encoding="utf-8"):
        sys.exit("homicide4: the third homicide patch must be applied first (homicide_culprits3.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("homicide4: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", *FILES, check=False)
            sys.exit("homicide4: the diff did not apply:\n" + r.stdout + r.stderr)
        print("homicide4: applied")
    text = h.read_text(encoding="utf-8")
    if NOTE.split("\n", 1)[0] not in text:
        h.write_text(text.rstrip("\n") + "\n\n\n" + NOTE, encoding="utf-8")


if __name__ == "__main__":
    main()
